// SPDX-License-Identifier: GPL-3.0-or-later
// Native-only storage ABI. Actual addresses are written and consumed on the
// GPU; JavaScript sees only the browser's opaque resource objects. A logical
// renderer buffer can exceed the browser's per-shared-allocation size limit.
template<class T> struct OmwPaged {
    const unsigned long long* pages;
    T* direct;
    unsigned long long first;
    __device__ OmwPaged(const unsigned long long* table):pages(table),direct(nullptr),first(0) {}
    __device__ OmwPaged(T* pointer):pages(nullptr),direct(pointer),first(0) {}
    template<class U> __device__ OmwPaged(const OmwPaged<U>& other):pages(other.pages),direct(other.direct),first(other.first) {}
    __device__ T& operator[](unsigned long long index) const {
        index+=first;
        if(direct)return direct[index];
        unsigned long long bytes=index*sizeof(T);
        return *reinterpret_cast<T*>(pages[bytes>>26]+(bytes&67108863ull));
    }
    __device__ OmwPaged operator+(unsigned long long offset) const {
        OmwPaged result=*this;result.first+=offset;return result;
    }
};

// SPDX-License-Identifier: GPL-3.0-or-later
// OSG captures row-vector application * inherited-stage matrices. Their raw
// storage is the column-vector transpose, so compose post * application here.
// Each invocation owns one matrix; finish all reads before writing it in place.
__device__ void compose_positioned_matrix(OmwPaged<unsigned int> descriptors,unsigned int matrix,OmwPaged<const unsigned int> positioned,unsigned int post) {


    float result[16];
    for(unsigned int col=0;col<4;col++)for(unsigned int row=0;row<4;row++) {
        float value=0.0f;
        for(unsigned int k=0;k<4;k++)value+=__uint_as_float(positioned[post+k*4+row])
            *__uint_as_float(descriptors[matrix+col*4+k]);
        result[col*4+row]=value;
    }
    for(unsigned int k=0;k<16;k++)descriptors[matrix+k]=__float_as_uint(result[k]);
}
__global__ void prepare_fixed_matrices(const unsigned long long* omw_pages_descriptors,const unsigned long long* omw_pages_positioned,unsigned int draw_count) {
OmwPaged<unsigned int> descriptors(omw_pages_descriptors);
OmwPaged<const unsigned int> positioned(omw_pages_positioned);

    unsigned int i=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(i>=draw_count*8u)return;
    unsigned int draw=i/8u,light=i%8u,d=draw*368u,table=descriptors[d+3u];
    if(table==0u||(descriptors[d]&(1u<<light))==0u)return;
    unsigned int post=positioned[table-1u+light];
    if(post!=0u)compose_positioned_matrix(descriptors,d+48u+light*40u+24u,positioned,post-1u);
}
__global__ void prepare_texgen_matrices(const unsigned long long* omw_pages_descriptors,const unsigned long long* omw_pages_positioned,unsigned int draw_count) {
OmwPaged<unsigned int> descriptors(omw_pages_descriptors);
OmwPaged<const unsigned int> positioned(omw_pages_positioned);

    unsigned int i=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(i>=draw_count*4u)return;
    unsigned int d=i*36u,post=descriptors[d+3u];
    if(post==0u||descriptors[d]==0u||descriptors[d+1u]!=5u)return;
    compose_positioned_matrix(descriptors,d+20u,positioned,post-1u);
}
